28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = telephone;
90	    }
91	
92	    public String getEmail() {
93	        return this.email;
94	    }
95	
96	    public void setEmail(String email) {
97	        this.email = email;
98	    }
99	
100	    public LocalDate getRegistrationDate() {
101	        return this.registrationDate;
102	    }
103	
104	    public void setRegistrationDate(LocalDate registrationDate) {
105	        this.registrationDate = registrationDate;
106	    }
107	
108	    public String getCustomerCode() {
109	        return this.customerCode;
110	    }
111	
112	    public void setCustomerCode(String customerCode) {
113	        this.customerCode = customerCode;
114	    }
115	
116	    public String getHouseholdId() {
117	        return this.householdId;
118	    }
119	
120	    public void setHouseholdId(String householdId) {
121	        this.householdId = householdId;
122	    }
123	
124	    /**
125	     * When no registration date is supplied, default it to the server's current date.
126	     * Running on {@link PrePersist} keeps this invariant true for every create path
127	     * (any controller, bulk import or test fixture) rather than a single entry point.
128	     */
129	    @PrePersist
130	    protected void onCreate() {
131	        if (this.registrationDate == null) {
132	            this.registrationDate = LocalDate.now();
133	        }
134	    }
135	
136	    protected Set<Pet> getPetsInternal() {
137	        if (this.pets == null) {
138	            this.pets = new HashSet<>();
139	        }
140	        return this.pets;
141	    }
142	
143	    protected void setPetsInternal(Set<Pet> pets) {
144	        this.pets = pets;
145	    }
146	
147	    public List<Pet> getPets() {
148	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
149	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
150	        return Collections.unmodifiableList(sortedPets);
151	    }
152	
153	    public void setPets(List<Pet> pets) {
154	        this.pets = new HashSet<>(pets);
155	    }
156	
157	    public void addPet(Pet pet) {
158	        getPetsInternal().add(pet);
159	        pet.setOwner(this);
160	    }
161	
162	    /**
163	     * Return the Pet with the given name, or null if none found for this Owner.
164	     *
165	     * @param name to test
166	     * @return true if pet name is already in use
167	     */
168	    public Pet getPet(String name) {
169	        return getPet(name, false);
170	    }
171	
172	    /**
173	     * Return the Pet with the given name, or null if none found for this Owner.
174	     *
175	     * @param name to test
176	     * @return true if pet name is already in use
177	     */
178	    public Pet getPet(String name, boolean ignoreNew) {
179	        name = name.toLowerCase();
180	        for (Pet pet : getPetsInternal()) {
181	            if (!ignoreNew || !pet.isNew()) {
182	                String compName = pet.getName();
183	                compName = compName.toLowerCase();
184	                if (compName.equals(name)) {
185	                    return pet;
186	                }
187	            }
188	        }
189	        return null;
190	    }
191	
192	    public Pet getPet(Integer petId) {
193	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
194	    }
195	
196	    @Override
197	    public String toString() {
198	        return new ToStringCreator(this)
199	
200	            .append("id", this.getId())
201	            .append("new", this.isNew())
202	            .append("lastName", this.getLastName())
203	            .append("firstName", this.getFirstName())
204	            .append("address", this.address)
205	            .append("city", this.city)
206	            .append("telephone", this.telephone)
207	            .append("email", this.email)
208	            .append("registrationDate", this.registrationDate)
209	            .append("customerCode", this.customerCode)
210	            .append("householdId", this.householdId)
211	            .toString();
212	    }
213	}
