37	/**
38	 * Mostly used as a facade for all Petclinic controllers
39	 * Also a placeholder for @Transactional and @Cacheable annotations
40	 *
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Service
45	public class ClinicServiceImpl implements ClinicService {
46	
47	    private final PetRepository petRepository;
48	    private final VetRepository vetRepository;
49	    private final OwnerRepository ownerRepository;
50	    private final VisitRepository visitRepository;
51	    private final SpecialtyRepository specialtyRepository;
52	    private final PetTypeRepository petTypeRepository;
53	    private final OwnerMapper ownerMapper;
54	
55	    public ClinicServiceImpl(
56	        PetRepository petRepository,
57	        VetRepository vetRepository,
58	        OwnerRepository ownerRepository,
59	        VisitRepository visitRepository,
60	        SpecialtyRepository specialtyRepository,
61	        PetTypeRepository petTypeRepository,
62	        OwnerMapper ownerMapper) {
63	        this.petRepository = petRepository;
64	        this.vetRepository = vetRepository;
65	        this.ownerRepository = ownerRepository;
66	        this.visitRepository = visitRepository;
67	        this.specialtyRepository = specialtyRepository;
68	        this.petTypeRepository = petTypeRepository;
69	        this.ownerMapper = ownerMapper;
70	    }
71	
72	    @Override
73	    @Transactional(readOnly = true)
74	    public Collection<Pet> findAllPets() throws DataAccessException {
75	        return petRepository.findAll();
76	    }
77	
78	    @Override
79	    @Transactional(readOnly = true)
80	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
81	        return petRepository.findAll(pageable);
82	    }
83	
84	    @Override
85	    @Transactional
86	    public void deletePet(Pet pet) throws DataAccessException {
87	        petRepository.delete(pet);
88	    }
89	
90	    @Override
91	    @Transactional(readOnly = true)
92	    public Visit findVisitById(int visitId) throws DataAccessException {
93	        return findEntityById(() -> visitRepository.findById(visitId));
94	    }
95	
96	    @Override
97	    @Transactional(readOnly = true)
98	    public Collection<Visit> findAllVisits() throws DataAccessException {
99	        return visitRepository.findAll();
100	    }
101	
102	    @Override
103	    @Transactional
104	    public void deleteVisit(Visit visit) throws DataAccessException {
105	        visitRepository.delete(visit);
106	    }
107	
108	    @Override
109	    @Transactional(readOnly = true)
110	    public Vet findVetById(int id) throws DataAccessException {
111	        return findEntityById(() -> vetRepository.findById(id));
112	    }
113	
114	    @Override
115	    @Transactional(readOnly = true)
116	    public Collection<Vet> findAllVets() throws DataAccessException {
117	        return vetRepository.findAll();
118	    }
119	
120	    @Override
121	    @Transactional
122	    public void saveVet(Vet vet) throws DataAccessException {
123	        vetRepository.save(vet);
124	    }
125	
126	    @Override
127	    @Transactional
128	    public void deleteVet(Vet vet) throws DataAccessException {
129	        vetRepository.delete(vet);
130	    }
131	
132	    @Override
133	    @Transactional(readOnly = true)
134	    public Collection<Owner> findAllOwners() throws DataAccessException {
135	        return ownerRepository.findAll();
136	    }
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
141	        if (lastName != null) {
142	            return ownerRepository.findByLastName(lastName, pageable);
143	        }
144	        return ownerRepository.findAll(pageable);
145	    }
146	
147	    @Override
148	    @Transactional
149	    public void deleteOwner(Owner owner) throws DataAccessException {
150	        ownerRepository.delete(owner);
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public PetType findPetTypeById(int petTypeId) {
156	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
157	    }
158	
159	    @Override
160	    @Transactional(readOnly = true)
161	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
162	        return petTypeRepository.findAll();
163	    }
164	
165	    @Override
166	    @Transactional
167	    public void savePetType(PetType petType) throws DataAccessException {
168	        petTypeRepository.save(petType);
169	    }
170	
171	    @Override
172	    @Transactional
173	    public void deletePetType(PetType petType) throws DataAccessException {
174	        petTypeRepository.delete(petType);
175	    }
176	
177	    @Override
178	    @Transactional(readOnly = true)
179	    public Specialty findSpecialtyById(int specialtyId) {
180	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
181	    }
182	
183	    @Override
184	    @Transactional(readOnly = true)
185	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
186	        return specialtyRepository.findAll();
187	    }
188	
189	    @Override
190	    @Transactional
191	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
192	        specialtyRepository.save(specialty);
193	    }
194	
195	    @Override
196	    @Transactional
197	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
198	        specialtyRepository.delete(specialty);
199	    }
200	
201	    @Override
202	    @Transactional(readOnly = true)
203	    public Collection<PetType> findPetTypes() throws DataAccessException {
204	        return petRepository.findPetTypes();
205	    }
206	
207	    @Override
208	    @Transactional(readOnly = true)
209	    public Owner findOwnerById(int id) throws DataAccessException {
210	        return findEntityById(() -> ownerRepository.findById(id));
211	    }
212	
213	    @Override
214	    @Transactional(readOnly = true)
215	    public Pet findPetById(int id) throws DataAccessException {
216	        return findEntityById(() -> petRepository.findById(id));
217	    }
218	
219	    @Override
220	    @Transactional
221	    public void savePet(Pet pet) throws DataAccessException {
222	        pet.setType(findPetTypeById(pet.getType().getId()));
223	        petRepository.save(pet);
224	    }
225	
226	    @Override
227	    @Transactional
228	    public void saveVisit(Visit visit) throws DataAccessException {
229	        visitRepository.save(visit);
230	
231	    }
232	
233	    @Override
234	    @Transactional(readOnly = true)
235	    public Collection<Vet> findVets() throws DataAccessException {
236	        return vetRepository.findAll();
237	    }
238	
239	    @Override
240	    @Transactional
241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.getCustomerCode() == null) {
243	            owner.setCustomerCode(generateCustomerCode(owner));
244	        }
245	        ownerRepository.save(owner);
246	
247	    }
248	
249	    /**
250	     * Build a {@code customerCode} of the form {@code <LAST3>-<NNNN>}: the upper-cased first
251	     * three letters of the owner's last name, a hyphen, and a global 4-digit zero-padded
252	     * sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
253	     */
254	    private String generateCustomerCode(Owner owner) {
255	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
256	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
257	        int sequence = ownerRepository.findAll().size() + 1;
258	        return String.format("%s-%04d", last3, sequence);
259	    }
260	
261	    @Override
262	    @Transactional(readOnly = true)
263	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
264	        return ownerRepository.findByLastName(lastName);
265	    }
266	
267	    @Override
268	    @Transactional(readOnly = true)
269	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
270	        String normalized = ownerMapper.normalizeTelephone(telephone);
271	        if (normalized == null) {
272	            return false;
273	        }
274	        return ownerRepository.findAll().stream()
275	            .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
276	            .anyMatch(normalized::equals);
277	    }
278	
279	    @Override
280	    @Transactional(readOnly = true)
281	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
282	        String normalizedLastName = normalizeHouseholdValue(lastName);
283	        String normalizedAddress = normalizeHouseholdValue(address);
284	        if (normalizedLastName == null || normalizedAddress == null) {
285	            return false;
286	        }
287	        return ownerRepository.findAll().stream()
288	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
289	    }
290	
291	    /**
292	     * Canonicalize a last name or address for household comparison: trim, collapse every run of
293	     * whitespace to a single space and lower-case the result, so values that differ only in
294	     * letter case or incidental whitespace are treated as equal.
295	     */
296	    private String normalizeHouseholdValue(String value) {
297	        if (value == null) {
298	            return null;
299	        }
300	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
301	    }
302	
303	    /**
304	     * Single definition of household membership: an owner belongs to the household identified by
305	     * the given already-normalized last name and address when its own normalized last name and
306	     * address match. Keeping this in one place means the household-equality rule is changed once.
307	     */
308	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
309	        return normalizedLastName.equals(normalizeHouseholdValue(existing.getLastName()))
310	            && normalizedAddress.equals(normalizeHouseholdValue(existing.getAddress()));
311	    }
312	
313	    @Override
314	    @Transactional
315	    public String assignHousehold(Owner owner) throws DataAccessException {
316	        String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
317	        owner.setHouseholdId(householdId);
318	        String normalizedLastName = normalizeHouseholdValue(owner.getLastName());
319	        String normalizedAddress = normalizeHouseholdValue(owner.getAddress());
320	        if (normalizedLastName != null && normalizedAddress != null) {
321	            // Back-fill existing members of the household so the joining owner and the
322	            // owner(s) already at the address share the same stable identifier.
323	            for (Owner existing : ownerRepository.findAll()) {
324	                if (existing.getHouseholdId() == null
325	                    && inHousehold(existing, normalizedLastName, normalizedAddress)) {
326	                    existing.setHouseholdId(householdId);
327	                    ownerRepository.save(existing);
328	                }
329	            }
330	        }
331	        return householdId;
332	    }
333	
334	    /**
335	     * Derive a stable household identifier from the normalized last name and address, so that
336	     * every owner sharing a household (same last name and address, compared case-insensitively
337	     * with internal whitespace collapsed) maps to the same value. The identifier is the first
338	     * eight upper-case hex characters of the SHA-256 of {@code <lastName>|<address>}, prefixed
339	     * with {@code 'H-'} (e.g. {@code H-3F5A9C2E}).
340	     */
